403:     pulseTokens = 0;
404:     place(first, {
405:       type: "thinking",
406:       id: `thinking:${first.id}`,
407:       pulse: {
408:         id: first.id,
409:         text,
410:         tokens: tokens > 0 ? tokens : undefined,
411:         seconds: eventDurationSeconds(first.createdAt, last.createdAt),
412:       },
413:     });
414:   };
415: 
416:   for (const event of events) {
417:     const tokens = event.presentation?.tokensThinking ?? 0;
418:     thinkingTokens += tokens;
419:     pulseTokens += tokens;
420:     if (event.id === receiptId) {
421:       flushPulse();
422:       receipt = event;
423:       continue;
424:     }
425:     const fold = calls.byEvent.get(event.id);
426:     if (fold !== undefined && fold.opener !== event.id) continue;
427:     if (isTechnical(fold?.row ?? event)) {
428:       technical.push(fold?.row ?? event);
429:       continue;
430:     }
431:     if (isThinkingPulse(event)) {
432:       pulse.push(event);
433:       continue;
434:     }
435:     flushPulse();
436:     if (event.id === responseId) continue;
437: 
438:     if (fold !== undefined) {
439:       turnFor(event).events.push(event);
440:       if (calls.nested.has(fold.key)) continue;
441:       place(event, { type: "call", call: builtCall(fold, calls) });
442:       continue;
443:     }
444: 
445:     const turn = turnFor(event);
446:     turn.events.push(event);
447:     if (event.kind === "message") {
448:       turn.segments.push({ lead: event, nodes: [{ type: "message", id: `message:${event.id}`, event }] });
449:       continue;
450:     }
451:     place(event, { type: "notice", id: `notice:${event.id}`, event });
452:   }
453:   flushPulse();
454: 
455:   const blocks: ActivityBlock[] = drafts
456:     .map((draft, index) => finishTurn(draft, settled || index + 1 < drafts.length))
457:     .filter((turn): turn is ActivityTurn => turn !== undefined)
458:     .map((turn) => ({ type: "turn" as const, turn }));
459:   if (receipt) blocks.push({ type: "receipt", event: receipt, thinkingTokens, usageWindow });
460:   return { blocks, technical };
461: }
462: 
463: /**
464:  * Closes a turn: a subagent's stretch moves under the row that started it,
465:  * and once the turn itself has closed, a call it never ended reads as
466:  * interrupted rather than as work still in flight.
467:  */
468: function finishTurn(draft: TurnDraft, closed: boolean): ActivityTurn | undefined {
469:   const segments = draft.segments
470:     .map((segment, index) => ({
471:       id: `segment:${draft.ordinal}:${index}`,
472:       lead: segment.lead,
473:       nodes: closed ? markInterrupted(nestSubagents(segment.nodes)) : nestSubagents(segment.nodes),
474:     }))
475:     .filter((segment) => segment.nodes.length > 0);
476:   if (segments.length === 0) return undefined;
477:   const named = turnTitle(segments);
478:   return {
479:     id: `turn:${draft.ordinal}`,
480:     turnId: draft.turnId,
481:     ordinal: draft.ordinal,
482:     title: named?.title,
483:     titleFrom: named?.id,
484:     segments,
485:     events: draft.events,
486:     status: turnStatus(segments, closed),
487:   };
488: }
489: 
490: /** A turn is named by the first thing the worker said while running it. */
491: function turnTitle(segments: ActivitySegment[]): { title: string; id: number } | undefined {
492:   for (const segment of segments) {
493:     for (const node of segment.nodes) {
494:       if (node.type !== "message") continue;
495:       const title = titleFromMessage(node.event);
496:       if (title !== undefined) return { title, id: node.event.id };
497:     }
498:   }
499:   return undefined;
500: }
501: 
502: function titleFromMessage(event: TaskEventView): string | undefined {
503:   const text = eventText(event);
504:   if (text === undefined) return undefined;
505:   const line = (text.split("\n").find((value) => value.trim() !== "") ?? "").trim();
506:   return line === "" ? undefined : clip(line, 80);
507: }
508: 
509: function turnStatus(segments: ActivitySegment[], closed: boolean): ActivityStatus {
510:   const flatten = (nodes: ActivityNode[]): ActivityNode[] =>
511:     nodes.flatMap((node) => (node.type === "subagent" ? [node, ...flatten(node.subagent.nodes)] : [node]));
512:   const nodes = flatten(segments.flatMap((segment) => segment.nodes));
513:   if (nodes.some((node) => node.type === "notice" && node.event.type === "needs_input")) return "needs_input";
514:   if (nodes.some(nodeFailed)) return "failed";
515:   if (!closed && nodes.some(nodeRunning)) return "running";
516:   return "done";
517: }
518: 
519: function nodeFailed(node: ActivityNode): boolean {
520:   if (node.type === "call") return node.call.status === "failed";
521:   if (node.type === "notice") return node.event.phase === "failed";
522:   return false;
523: }
524: 
525: function nodeRunning(node: ActivityNode): boolean {
526:   return node.type === "call" && node.call.status === "running";
527: }
528: 
529: // ---------------------------------------------------------------------------
530: // Calls
531: // ---------------------------------------------------------------------------
532: 
533: /** The agent's own record of a call, on a turn that ran over ACP. */
534: const AGENT_CALL_TYPES = new Set(["agent.tool_call", "agent.tool_call_update"]);
535: 
536: const CALL_KINDS = new Set<TaskEventView["kind"]>(["tool", "command", "file"]);
537: 
538: /** A heartbeat that only says a call is still going; its row already says so. */
539: const TOOL_PROGRESS_TYPE = "agent.tool_progress";
540: 
541: interface CallFold {
542:   key: string;
543:   actionId: string;
544:   turnId?: number;
545:   /** The id of the row that opened this call. */
546:   opener: number;
547:   row: TaskEventView;
548:   events: TaskEventView[];
549: }
550: 
551: interface CallFolds {
552:   /** Every row that carried a call id, pointed at the call it belongs to. */
553:   byEvent: Map<number, CallFold>;
554:   /** The calls a delegating call reported as its own, by the parent's key. */
555:   childrenOf: Map<string, CallFold[]>;
556:   /** The keys of calls that hang under another call rather than on their own. */
557:   nested: Set<string>;
558: }
559: 
560: function callId(event: TaskEventView): string | undefined {
561:   return event.actionId === undefined || event.actionId === "" ? undefined : event.actionId;
562: }
563: 
564: /**
565:  * Whether a row belongs to a call already open. A provider posts some rows
566:  * before it has told us which turn it is on, and an unknown turn is not a
567:  * different turn — it is the same call still reporting.
568:  */
569: function sameCall(fold: CallFold, event: TaskEventView): boolean {
570:   return fold.turnId === undefined || event.turnId === undefined || fold.turnId === event.turnId;
571: }
572: 
573: /**
574:  * Folds every row a provider sent for one tool call into a single record,
575:  * keyed by that call's own id. A resumed session replays the whole prior
576:  * transcript, so a call that already finished arrives again as a fresh start
577:  * under its original id; that replay lands back on the record it already has
578:  * rather than opening a second one.
579:  */
580: function foldCalls(events: TaskEventView[]): CallFolds {
581:   const byEvent = new Map<number, CallFold>();
582:   const byAction = new Map<string, CallFold>();
583:   const opened: CallFold[] = [];
584:   for (const event of events) {
585:     const actionId = callId(event);
586:     if (actionId === undefined) continue;
587:     const fold = byAction.get(actionId);
588:     if (fold !== undefined && sameCall(fold, event) && !reopens(fold.row, event)) {
589:       fold.events.push(event);
590:       fold.turnId = fold.turnId ?? event.turnId;
591:       byEvent.set(event.id, fold);
592:       if (!replays(fold.row, event)) fold.row = settleAction(fold.row, event);
593:       continue;
594:     }
595:     // A heartbeat only says a call is still going; it never opens one.
596:     if (event.type === TOOL_PROGRESS_TYPE) continue;
597:     const call: CallFold = {
598:       key: `${actionId}#${event.id}`,
599:       actionId,
600:       turnId: event.turnId,
601:       opener: event.id,
602:       row: event,
603:       events: [event],
604:     };
605:     byAction.set(actionId, call);
606:     byEvent.set(event.id, call);
607:     opened.push(call);
608:   }
609: 
610:   const childrenOf = new Map<string, CallFold[]>();
611:   const nested = new Set<string>();
612:   const first = new Map<string, CallFold>();
613:   for (const call of opened) if (!first.has(call.actionId)) first.set(call.actionId, call);
614:   for (const call of opened) {
615:     const parent = parentActionId(call.row);
616:     const owner = parent === undefined ? undefined : first.get(parent);
617:     if (owner === undefined || owner === call) continue;
618:     childrenOf.set(owner.key, [...(childrenOf.get(owner.key) ?? []), call]);
619:     nested.add(call.key);
620:   }
621:   return { byEvent, childrenOf, nested };
622: }
623: 
624: function builtCall(fold: CallFold, folds: CallFolds): ActivityCall {
625:   const last = fold.events[fold.events.length - 1] ?? fold.row;
626:   const terminal = fold.row.phase === "completed" || fold.row.phase === "failed";
627:   return {
628:     id: `call:${fold.turnId ?? 0}:${fold.actionId}`,
629:     actionId: fold.actionId,
630:     event: fold.row,
631:     events: fold.events,
632:     children: (folds.childrenOf.get(fold.key) ?? []).map((child) => builtCall(child, folds)),
633:     status: fold.row.phase === "failed" ? "failed" : terminal ? "done" : "running",
634:     startedAt: fold.events[0]?.createdAt ?? fold.row.createdAt,
635:     endedAt: terminal ? last.createdAt : undefined,
636:   };
637: }
638: 
639: /**
640:  * A call that has not reported a terminal phase on a turn that already closed
641:  * never finished; it did not keep running either.
642:  */
643: function markInterrupted(nodes: ActivityNode[]): ActivityNode[] {
644:   const call = (value: ActivityCall): ActivityCall => ({
645:     ...value,
646:     status: value.status === "running" ? "interrupted" : value.status,
647:     children: value.children.map(call),
648:   });
649:   return nodes.map((node) => {
650:     if (node.type === "subagent") {
651:       const status = node.subagent.status === "running" ? "interrupted" : node.subagent.status;
652:       return { ...node, subagent: { ...node.subagent, status, nodes: markInterrupted(node.subagent.nodes) } };
653:     }
654:     return node.type === "call" ? { type: "call", call: call(node.call) } : node;
655:   });
656: }
657: 
658: // ---------------------------------------------------------------------------
659: // Subagents
660: // ---------------------------------------------------------------------------
661: 
662: export const SUBAGENT_STARTED_TITLE = "Subagent started";
663: export const SUBAGENT_FINISHED_TITLE = "Subagent finished";
664: 
665: /**
666:  * Subagent runs nest by bracketing: a start opens a group, its stop closes it,
667:  * and a start that arrives while another group is still open sits inside it.
668:  * A row that names the run it belongs to (a hook `agent_id`, or a call whose
669:  * parent is the launching call) goes there even when the groups interleave;
670:  * any other row goes to the innermost open group. A start that never stops
671:  * closes with everything that followed it, still marked as running.
672:  */
673: function nestSubagents(nodes: ActivityNode[]): ActivityNode[] {
674:   interface Frame {
675:     id: string;
676:     start: TaskEventView;
677:     parent: Frame | undefined;
678:     nodes: ActivityNode[];
679:     belongs: (event: TaskEventView) => boolean;
680:     done: boolean;
681:   }
682:   const root: ActivityNode[] = [];
683:   const open: Frame[] = [];
684:   const wrap = (frame: Frame): ActivityNode => ({
685:     type: "subagent",
686:     subagent: {
687:       id: `subagent:${frame.id}`,
688:       label: subagentLabel(frame.start),
689:       start: frame.start,
690:       nodes: frame.nodes,
691:       status: frame.done ? "done" : "running",
692:     },
693:   });
694:   const close = (frame: Frame) => {
695:     const index = open.indexOf(frame);
696:     open.splice(index, 1);
697:     for (const inner of open.slice(index)) {
698:       if (inner.parent === frame) inner.parent = frame.parent;
699:     }
700:     (frame.parent && open.includes(frame.parent) ? frame.parent.nodes : root).push(wrap(frame));
701:   };
702: 
703:   for (const node of nodes) {
704:     const boundary = node.type === "notice" ? subagentBoundary(node.event) : undefined;
705:     if (node.type === "notice" && boundary?.role === "start" && !open.some((frame) => frame.id === boundary.id)) {
706:       open.push({
707:         id: boundary.id,
708:         start: node.event,
709:         parent: open.at(-1),
710:         nodes: [],
711:         belongs: subagentMembership(node.event, boundary.id),
712:         done: false,
713:       });
714:       continue;
715:     }
716:     if (boundary?.role === "stop") {
717:       const frame = innermost(open, (candidate) => candidate.id === boundary.id);
718:       if (frame !== undefined) {
719:         frame.nodes.push(node);
720:         frame.done = true;
721:         close(frame);
722:         continue;
723:       }
724:     }
725:     const events = nodeEvents(node);
726:     const owner = innermost(open, (frame) => events.some(frame.belongs)) ?? open.at(-1);
727:     (owner?.nodes ?? root).push(node);
728:   }
729:   while (open.length > 0) close(open[open.length - 1]);
730:   return root;
731: }
732: 
733: function innermost<T>(frames: T[], matches: (frame: T) => boolean): T | undefined {
734:   for (let index = frames.length - 1; index >= 0; index--) {
735:     if (matches(frames[index])) return frames[index];
736:   }
737:   return undefined;
738: }
739: 
740: function subagentBoundary(event: TaskEventView): { id: string; role: "start" | "stop" } | undefined {
741:   if (event.title === "SubagentStart" || event.title === "SubagentStop" || event.title === "Spawned subagent") {
742:     const id = rawString(event, "agent_id");
743:     if (id === undefined) return undefined;
744:     return { id, role: event.title === "SubagentStop" ? "stop" : "start" };
745:   }
746:   if (event.title === SUBAGENT_STARTED_TITLE || event.title === SUBAGENT_FINISHED_TITLE) {
747:     // The streamed pair shares `task_id`; the hook pair shares `agent_id`
748:     // under the same normalized titles since Rust aligns them.
749:     const id = rawString(event, "task_id") ?? rawString(event, "agent_id");
750:     return id === undefined ? undefined : { id, role: event.title === SUBAGENT_STARTED_TITLE ? "start" : "stop" };
751:   }
752:   return undefined;
753: }
754: 
755: /**
756:  * A hook pair stamps every row it owns with the same `agent_id`. A streamed
757:  * pair does not: it names the tool call that launched the subagent, and the
758:  * subagent's own calls point back at it as their parent.
759:  */
760: function subagentMembership(start: TaskEventView, id: string): (event: TaskEventView) => boolean {
761:   if (rawString(start, "agent_id") !== undefined) {
762:     return (event) => rawString(event, "agent_id") === id;
763:   }
764:   const toolUseId = rawString(start, "tool_use_id");
765:   return (event) => toolUseId !== undefined && parentActionId(event) === toolUseId;
766: }
767: 
768: function subagentLabel(event: TaskEventView): string {
769:   const name = rawString(event, "agent_type") ?? (event.title === SUBAGENT_STARTED_TITLE ? event.detail : undefined);
770:   return name !== undefined && name !== "" ? `Subagent · ${name}` : "Subagent";
771: }
772: 
773: // ---------------------------------------------------------------------------
774: // What belongs in the story, and what is bookkeeping
775: // ---------------------------------------------------------------------------
776: 
777: export const ACTIVITY_SKIPPED_TITLE = "Some activity was not recorded";
778: /** Every provider's reasoning blocks share this title; it is how they fold. */
779: export const REASONING_TITLE = "Thinking";
780: const USAGE_WINDOW_TITLE = "Usage window";
781: 
782: /** Broker rows that record how a run was managed, not what it did. */
783: const BOOKKEEPING_TYPES = new Set([
784:   "created",
785:   "queued",
786:   "started",
787:   "worker_spawned",
788:   "completed",
789:   "archived",
790:   "unarchived",
791:   "session_captured",
792:   "session_reused",
793:   "worker_stderr",
794:   "heartbeat",
795:   "handoff_brief",
796: ]);
797: 
798: /** The broker's own record of output it could not keep. */
799: const SKIPPED_TYPES = new Set(["line_dropped", "event_dropped", "events_truncated"]);
800: 
801: function isTechnical(event: TaskEventView): boolean {
802:   if (event.minor === true) return true;
803:   if (BOOKKEEPING_TYPES.has(event.type) || event.type === TOOL_PROGRESS_TYPE) return true;
804:   // A raw payload has no words a reader can use; it stays behind the toggle.
805:   if (event.kind === "raw") return true;
806:   if (event.kind === "usage") return true;
807:   // A usage-window notice earns its place only when it says what was limited
808:   // and for how long; the bare marker repeats without telling a reader
809:   // anything.
810:   if (event.title === USAGE_WINDOW_TITLE && (event.detail === undefined || event.detail === event.title)) {
811:     return true;
812:   }
813:   return event.kind === "tool" && event.detail === undefined && event.presentation === undefined;
814: }
815: 
816: function handoffBriefTier(event: TaskEventView): HandoffBriefTier | undefined {
817:   if (event.type !== "handoff_brief") return undefined;
818:   const tier = event.detail?.split(/\s+/, 1)[0];
819:   return tier === "verbatim" || tier === "digest" ? tier : undefined;
820: }
821: 
822: function isThinkingPulse(event: TaskEventView): boolean {
823:   return event.kind === "reasoning" && event.title === REASONING_TITLE;
824: }
825: 
826: /**
827:  * The readable part of one stretch of thinking.
828:  *
829:  * Providers that stream reasoning resend the whole block on every update, so a
830:  * block that starts with the one before it replaces that one instead of piling
831:  * up beside it. Blocks the provider redacted contribute nothing here — they
832:  * still lengthen the stretch, they just cannot be read.
833:  */
834: function mergeReasoning(events: TaskEventView[]): string | undefined {
835:   const blocks: string[] = [];
836:   for (const event of events) {
837:     const text = event.detail?.trim();
838:     if (text === undefined || text === "") continue;
839:     const previous = blocks[blocks.length - 1];
840:     if (previous !== undefined && text.startsWith(previous)) blocks[blocks.length - 1] = text;
841:     else blocks.push(text);
842:   }
843:   return blocks.length > 0 ? blocks.join("\n\n") : undefined;
844: }
845: 
846: /** Whether anything in this run is worth turning "Show thinking" on for. */
847: export function compositionHasThinking(composition: ActivityComposition): boolean {
848:   const inNodes = (nodes: ActivityNode[]): boolean =>
849:     nodes.some((node) => (node.type === "subagent" ? inNodes(node.subagent.nodes) : node.type === "thinking"));
850:   return composition.blocks.some(
851:     (block) => block.type === "turn" && block.turn.segments.some((segment) => inNodes(segment.nodes)),
852:   );
853: }
854: 
855: /**
856:  * Output goes missing a line at a time, so a lossy run can raise the notice
857:  * dozens of times. A reader needs to know once, with the total.
858:  */
859: function mergeSkipNotices(events: TaskEventView[]): TaskEventView[] {
860:   const counts = new Map<string, number>();
861:   let first: number | undefined;
862:   events.forEach((event, index) => {
863:     if (!SKIPPED_TYPES.has(event.type)) return;
864:     if (first === undefined) first = index;
865:     const skipped = parseSkipped(event.detail);
866:     if (skipped) counts.set(skipped.noun, (counts.get(skipped.noun) ?? 0) + skipped.count);
867:   });
868:   if (first === undefined) return events;
869: 
870:   const totals = [...counts]
871:     .map(([noun, count]) => `${count} ${noun}${count === 1 ? "" : "s"} skipped`)
872:     .join(" · ");
873:   const text = totals === "" ? ACTIVITY_SKIPPED_TITLE : `${ACTIVITY_SKIPPED_TITLE} — ${totals}`;
874:   return events.flatMap((event, index) => {
875:     if (!SKIPPED_TYPES.has(event.type)) return [event];
876:     if (index !== first) return [];
877:     return [{
878:       ...event,
879:       detail: totals === "" ? undefined : totals,
880:       presentation: { type: "signal" as const, text, level: "warning" as const },
881:     }];
882:   });
883: }
884: 
885: function parseSkipped(detail: string | undefined): { count: number; noun: string } | undefined {
886:   const match = detail?.match(/^(\d+) (line|event)s? skipped$/);
887:   return match ? { count: Number(match[1]), noun: match[2] } : undefined;
888: }
889: 
890: /**
891:  * The window a run is closest to filling, read off the last notice the provider
892:  * sent, so the receipt says how much headroom is left before the next run.
893:  */
894: function usageWindowSummary(events: TaskEventView[]): string | undefined {
895:   const notice = findLast(events, (event) => event.title === USAGE_WINDOW_TITLE);
896:   const windows = rawObject(rawObject(rawObject(notice && rawValue(notice))?.rate_limit_info)?.unifiedWindows);
897:   if (!windows) return undefined;
898:   let busiest: { utilization: number; resetsAt?: number } | undefined;
899:   for (const value of Object.values(windows)) {
900:     const window = rawObject(value);
901:     const utilization = window?.utilization;
902:     if (typeof utilization !== "number") continue;
903:     if (busiest && busiest.utilization >= utilization) continue;
904:     const resetsAt = window?.resetsAt;
905:     busiest = { utilization, resetsAt: typeof resetsAt === "number" ? resetsAt : undefined };
906:   }
907:   if (!busiest) return undefined;
908:   const percent = `${USAGE_WINDOW_TITLE} ${Math.round(busiest.utilization * 100)}%`;
909:   const resets = busiest.resetsAt === undefined ? undefined : absoluteTime(new Date(busiest.resetsAt * 1000));
910:   return resets === undefined ? percent : `${percent} · resets ${resets}`;
911: }
912: 
913: function closingMessageId(events: TaskEventView[]): number | undefined {
914:   const index = findLastIndex(
915:     events,
916:     (event) => event.kind === "message" && event.minor !== true && eventText(event) !== undefined,
917:   );
918:   if (index === -1) return undefined;
919:   const rest = events.slice(index + 1);
920:   // A run tidies up after it speaks — session bookkeeping, the worker's own
921:   // logging, the row that closes the task — and none of that makes the words
922:   // before it something other than the closing answer. A failure does, and
923:   // keeps the answer in the trace where it happened.
924:   return rest.every((event) => isTechnical(event) || event.kind === "usage" || event.kind === "lifecycle")
925:     ? events[index].id
926:     : undefined;
927: }
928: 
929: // ---------------------------------------------------------------------------
930: // Normalizing what providers send
931: // ---------------------------------------------------------------------------
932: 
933: /**
934:  * Drops the hook copies of calls the worker already reported itself.
935:  *
936:  * A worker whose hooks post to Oga reports every tool call twice on a turn
937:  * that also streams its own: once as a hook, once as the agent's own row. The
938:  * agent's row is the fuller one — it carries the diff, the files, and the
939:  * agent's own words for the call — so the hook copy goes. Hooks that are not
940:  * about a call at all say something no other row does and stay.
941:  */
942: export function withoutDuplicateHookCalls(events: TaskEventView[]): TaskEventView[] {
943:   const agentTurns = new Set<number | undefined>();
944:   const agentCalls = new Set<string>();
945:   for (const event of events) {
946:     if (!AGENT_CALL_TYPES.has(event.type)) continue;
947:     agentTurns.add(event.turnId);
