99: pub fn command_for(
100:     profile: &Profile,
101:     prompt: &str,
102:     cwd: &str,
103:     model: Option<&str>,
104:     effort: Option<&str>,
105:     oga_server: Option<OgaServer<'_>>,
106: ) -> Result<ProviderCommand, ProviderError> {
107:     command_for_with_options(
108:         profile,
109:         prompt,
110:         cwd,
