120: pub fn command_for_with_options(
121:     profile: &Profile,
122:     prompt: &str,
123:     cwd: &str,
124:     model: Option<&str>,
125:     options: CommandOptions<'_>,
126: ) -> Result<ProviderCommand, ProviderError> {
127:     let CommandOptions {
128:         hook_url,
129:         effort,
130:         oga_server,
131:     } = options;
132:     let model = model.unwrap_or(&profile.default_model);
133:     let argv = if let Some(command) = &profile.command {
134:         command
135:             .iter()
136:             .map(|part| {
137:                 part.replace("{prompt}", prompt)
138:                     .replace("{model}", model)
139:                     .replace("{cwd}", cwd)
140:                     .replace("{effort}", effort.unwrap_or(""))
141:             })
142:             .collect::<Vec<_>>()
143:     } else {
144:         match profile.provider {
145:             Provider::Claude => {
146:                 let skills = skills_dir(profile);
147:                 let hook_settings = hook_url.map(claude_hook_settings);
148:                 let mcp_config = oga_server.map(claude_mcp_config);
149:                 let mut a = vec![
150:                     "claude",
151:                     "-p",
152:                     "--output-format",
153:                     "stream-json",
154:                     "--verbose",
155:                     "--model",
156:                     model,
157:                 ];
158:                 if let Some(e) = effort {
159:                     a.extend(["--effort", e]);
160:                 }
161:                 a.extend([
162:                     "--permission-mode",
163:                     "bypassPermissions",
164:                     "--add-dir",
165:                     skills.as_str(),
166:                 ]);
167:                 if let Some(settings) = hook_settings.as_deref() {
168:                     a.extend(["--settings", settings]);
169:                 }
170:                 if let Some(c) = mcp_config.as_deref() {
171:                     a.extend(["--mcp-config", c]);
172:                 }
173:                 a.extend(["--", prompt]);
174:                 a.into_iter().map(String::from).collect()
175:             }
176:             Provider::Codex => {
177:                 let mut a = vec!["codex", "exec", "--json", "--model", model];
178:                 let effort_config =
179:                     effort.map(|value| format!("model_reasoning_effort=\"{value}\""));
180:                 if let Some(e) = effort {
181:                     a.extend(["-c", effort_config.as_deref().unwrap_or(e)]);
182:                 }
183:                 let oga_config = oga_server.map(codex_mcp_config);
184:                 if let Some([url, header]) = &oga_config {
185:                     a.extend(["-c", url.as_str(), "-c", header.as_str()]);
186:                 }
187:                 a.extend([
188:                     "--dangerously-bypass-approvals-and-sandbox",
189:                     "--cd",
190:                     cwd,
191:                     "--skip-git-repo-check",
192:                     prompt,
193:                 ]);
194:                 a.into_iter().map(String::from).collect()
195:             }
196:             Provider::OpenCode => {
197:                 let executable = opencode_executable(profile)?;
198:                 let mut a = vec![
199:                     executable.as_str(),
200:                     "run",
201:                     "--format",
202:                     "json",
203:                     "--model",
204:                     model,
205:                 ];
206:                 if let Some(e) = effort {
207:                     a.extend(["--variant", e]);
208:                 }
209:                 a.extend(["--dir", cwd, "--auto", prompt]);
210:                 a.into_iter().map(String::from).collect()
211:             }
212:             Provider::OpenCode2 => opencode2_run(profile, model, effort, None, prompt),
213:             Provider::Antigravity => vec![
214:                 "agy",
215:                 "--print",
216:                 prompt,
217:                 "--output-format",
218:                 "stream-json",
219:                 "--model",
220:                 model,
221:                 "--new-project",
222:                 "--add-dir",
223:                 cwd,
224:                 "--mode",
225:                 "accept-edits",
226:                 "--dangerously-skip-permissions",
227:             ]
228:             .into_iter()
229:             .map(String::from)
230:             .collect(),
231:             Provider::Pi => {
232:                 let mut a = vec!["pi", "--mode", "json", "--model", model];
233:                 if let Some(e) = effort {
234:                     a.extend(["--thinking", e]);
235:                 }
236:                 a.extend(["--no-approve", prompt]);
237:                 a.into_iter().map(String::from).collect()
238:             }
239:             Provider::Fx => fx_ask(prompt, None),
240:             Provider::Cursor => return Err(ProviderError::NoCommandLine("cursor")),
241:         }
242:     };
243:     Ok(ProviderCommand {
244:         argv,
245:         env: run_environment_for(profile, model),
246:         env_remove: unset_environment_for(profile),
247:     })
248: }
